/*
 * The region-decode probe (#791): fetch, load and store at the addresses
 * run.py lists, one probe at a time, on the split CPU in machine mode.
 *
 * Each probe of the table `probes` (probe_data.S, generated by run.py) is
 * three words: its kind, its address and, for a store, its value. Before each
 * probe the program stores the probe's table address to the report word, so
 * the testbench's log divides into one segment per probe. A load stores the
 * word it read to the report word + 4. A fetch calls its address, whose word
 * is `ret`. A trap, of any cause, stores mcause, mtval and mepc to the report
 * word + 8, + 12 and + 16, then resumes by the probe's kind (t2): a fetch at
 * the call's return, a load or a store past it, so every probe runs and
 * run.py grades the cause. The table's end stores DONE_WORD; a kind the
 * program does not know stores HALT_WORD.
 *
 * The program and the table sit in rom's first page, and the report words in
 * sram's first words, so no address it uses for itself is near a probed one.
 */
#define K_END 0
#define K_LOAD 1
#define K_FETCH 2
#define K_STORE 3

	.section .text.start, "ax"
	.globl _start
_start:
	la	t0, trap
	csrw	mtvec, t0
	li	s0, REPORT_ADDRESS
	la	s1, probes
next:
	lw	t2, 0(s1)		/* kind */
	lw	a0, 4(s1)		/* address */
	lw	a1, 8(s1)		/* value, for a store */
	sw	s1, 0(s0)		/* the mark: this probe's table address */
	beqz	t2, done
	li	t3, K_LOAD
	beq	t2, t3, load
	li	t3, K_FETCH
	beq	t2, t3, fetch
	li	t3, K_STORE
	beq	t2, t3, store
	j	halt
load:
	lw	t1, 0(a0)
	sw	t1, 4(s0)
	j	step
fetch:
	jalr	ra, 0(a0)
	j	step
store:
	sw	a1, 0(a0)
step:
	addi	s1, s1, 12
	j	next
done:
	li	t1, DONE_WORD
	sw	t1, 0(s0)
1:	j	1b
halt:
	li	t1, HALT_WORD
	sw	t1, 0(s0)
1:	j	1b

	.balign 4
trap:
	csrr	t4, mcause
	csrr	t5, mtval
	csrr	t6, mepc
	sw	t4, 8(s0)
	sw	t5, 12(s0)
	sw	t6, 16(s0)
	li	t3, K_FETCH
	bne	t2, t3, past
	csrw	mepc, ra
	mret
past:
	addi	t6, t6, 4
	csrw	mepc, t6
	mret
